/* begin src/cnt/dev/map/common.h */
/** TODO: should be merged with Map in fsi:: */
enum {FULL, EMPTY}; /* map status */
struct Map { /* helps to find remote particle */
    int  org0, org1, org2;
    int cnt0, cnt1, cnt2;
};

/* true if `i' is bigger than the number of remote particles */
static __device__ int endp(const Map m, int i) { return i >= m.cnt2; }

static __device__ int m2id(const Map m, int i) {
    /* return remote particle id */
    int m1, m2;
    int id;
    m1 = (int)(i >= m.cnt0);
    m2 = (int)(i >= m.cnt1);
    id = i + (m2 ? m.org2 : m1 ? m.org1 : m.org0);
    return id;
}
/* end src/cnt/dev/map/common.h */
/* begin src/cnt/dev/map/halo.h */
static __device__ int tex2map(int3 L, int zplane, float x, float y, float z, const int *starts, /**/ Map *m) {
    int cnt0, cnt1, cnt2, org0;
    int org1, org2;
    int xcenter, xstart, xcount;
    int ycenter, zcenter, zmy;
    bool zvalid;
    int count0, count1, count2;
    int cid0, cid1, cid2;

    xcenter = L.x / 2 + (int)floorf(x);
    xstart = max(0, xcenter - 1);
    xcount = min(L.x, xcenter + 2) - xstart;

    if (xcenter - 1 >= L.x || xcenter + 2 <= 0) return EMPTY;

    ycenter = L.y / 2 + (int)floorf(y);

    zcenter = L.z / 2 + (int)floorf(z);
    zmy = zcenter - 1 + zplane;
    zvalid = zmy >= 0 && zmy < L.z;

    count0 = count1 = count2 = 0;

    if (zvalid && ycenter - 1 >= 0 && ycenter - 1 < L.y) {
        cid0 = xstart + L.x * (ycenter - 1 + L.y * zmy);
        org0 = starts[cid0];
        count0 = starts[cid0 + xcount] - org0;
    }

    if (zvalid && ycenter >= 0 && ycenter < L.y) {
        cid1 = xstart + L.x * (ycenter + L.y * zmy);
        org1 = starts[cid1];
        count1 = starts[cid1 + xcount] - org1;
    }

    if (zvalid && ycenter + 1 >= 0 && ycenter + 1 < L.y) {
        cid2 = xstart + L.x * (ycenter + 1 + L.y * zmy);
        org2 = starts[cid2];
        count2 = starts[cid2 + xcount] - org2;
    }

    cnt0 = count0;
    cnt1 = count0 + count1;
    cnt2 = cnt1 + count2;

    org1 -= cnt0;
    org2 -= cnt1;

    m->org0 = org0; m->org1 = org1; m->org2 = org2;
    m->cnt0 = cnt0; m->cnt1 = cnt1; m->cnt2 = cnt2;
    return FULL;
}
/* end src/cnt/dev/map/halo.h */
/* begin src/cnt/dev/map/bulk.h */
static __device__ int r2map(int3 L, int zplane, int n, float x, float y, float z, const int *starts, /**/ Map *m) {
    /* coordinate [r] to map */
    int cnt0, cnt1, cnt2, org0;
    int org1, org2;
    int xcenter, xstart, xcount;
    int ycenter, zcenter, zmy;
    bool zvalid;
    int count0, count1, count2;
    int cid0, cid1, cid2;

    xcenter = min(L.x - 1, max(0, L.x / 2 + (int)floorf(x)));
    xstart = max(0, xcenter - 1);
    xcount = min(L.x, xcenter + 2) - xstart;
    if (xcenter - 1 >= L.x || xcenter + 2 <= 0) return EMPTY;
    ycenter = min(L.y - 1, max(0, L.y / 2 + (int)floorf(y)));
    zcenter = min(L.z - 1, max(0, L.z / 2 + (int)floorf(z)));
    zmy = zcenter - 1 + zplane;
    zvalid = zmy >= 0 && zmy < L.z;
    count0 = count1 = count2 = 0;
    if (zvalid && ycenter - 1 >= 0 && ycenter - 1 < L.y) {
        cid0 = xstart + L.x * (ycenter - 1 + L.y * zmy);
        org0 = starts[cid0];
        count0 = starts[cid0 + xcount] - org0;
    }
    if (zvalid && ycenter >= 0 && ycenter < L.y) {
        cid1 = xstart + L.x * (ycenter + L.y * zmy);
        org1 = starts[cid1];
        count1 = starts[cid1 + xcount] - org1;
    }

    if (zvalid && ycenter + 1 >= 0 && ycenter + 1 < L.y) {
        cid2 = xstart + L.x * (ycenter + 1 + L.y * zmy);
        org2 = starts[cid2];
        count2 = starts[cid2 + xcount] - org2;
    }

    cnt0 = count0;
    cnt1 = count0 + count1;
    cnt2 = cnt1 + count2;

    org1 -= cnt0;
    org2 -= cnt1;

    m->org0 = org0; m->org1 = org1; m->org2 = org2;
    m->cnt0 = cnt0; m->cnt1 = cnt1; m->cnt2 = cnt2;
    return FULL;
}
/* end src/cnt/dev/map/bulk.h */
/* begin src/cnt/dev/bulk.h */
static __device__ void f22p(float2 a, float2 b, float2 c, PairPa *p) {
    p->x  = a.x; p->y  = a.y; p->z  = b.x;
    p->vx = b.y; p->vy = c.x; p->vz = c.y;
}

static __device__ void fetch(int i, const float2 *pp, PairPa *p) {
    float2 a, b, c;
    a = __ldg(pp + 3 * i + 0);
    b = __ldg(pp + 3 * i + 1);
    c = __ldg(pp + 3 * i + 2);
    f22p(a, b, c, p);
}

template <typename Par>
__global__ void bulk(bool self, Par params, int3 L, int n_dst, const float2 *pp_dst,
                     const int *starts, const uint *ids_src, const float2 *pp_src,
                     float seed, /**/ float *ff_dst, float *ff_src) {
    Map m; /* see map/ */

    float fx, fy, fz, rnd;
    PairPa a, b;
    int i, gid, aid, zplane;
    float xforce, yforce, zforce;
    int mapstatus;
    int slot, objid, bid, sentry;
    uint code;

    gid = threadIdx.x + blockDim.x * blockIdx.x;
    aid = gid / 3;
    zplane = gid % 3;

    if (aid >= n_dst) return;

    fetch(aid, pp_dst, &a);
    mapstatus = r2map(L, zplane, n_dst, a.x, a.y, a.z, starts, /**/ &m);

    if (mapstatus == EMPTY) return;
    xforce = yforce = zforce = 0;
    for (i = 0; !endp(m, i); ++i) {
        slot = m2id(m, i);
        code = ids_src[slot];
        clist_decode_id(code, /**/ &objid, &bid);

        if (self && aid <= bid) continue;

        fetch(bid, pp_src, &b);

        rnd = rnd::mean0var1ii(seed, aid, bid);

        pair(params, a, b, rnd, /**/ &fx, &fy, &fz);

        xforce += fx;
        yforce += fy;
        zforce += fz;

        sentry = 3 * bid;
        atomicAdd(ff_src + sentry,     -fx);
        atomicAdd(ff_src + sentry + 1, -fy);
        atomicAdd(ff_src + sentry + 2, -fz);
    }

    atomicAdd(ff_dst + 3 * aid + 0, xforce);
    atomicAdd(ff_dst + 3 * aid + 1, yforce);
    atomicAdd(ff_dst + 3 * aid + 2, zforce);
}
/* end src/cnt/dev/bulk.h */
/* begin src/cnt/dev/halo.h */
template <typename Par>
static __device__
void interactions_one_p(Par params, int3 L, float seed, PairPa a, int aid,
                        const int *starts, const uint *ids_src, const float2 *pp_src,
                        /**/ float *ff_src, float *fA) {
    enum {X, Y, Z};
    Map m;
    int mapstatus;
    PairPa b;
    float fx, fy, fz;
    float xforce = 0, yforce = 0, zforce = 0;
    int zplane;
    int i, slot, oid, bid, sentry;
    uint code;
    float rnd;

    for (zplane = 0; zplane < 3; ++zplane) {
        mapstatus = tex2map(L, zplane, a.x, a.y, a.z, starts, /**/ &m);
        if (mapstatus == EMPTY) continue;
        for (i = 0; !endp(m, i); ++i) {
            slot = m2id(m, i);
            code = ids_src[slot];
            clist_decode_id(code, /**/ &oid, &bid);

            fetch(bid, pp_src, /**/ &b);
            rnd = rnd::mean0var1ii(seed, aid, bid);
            pair(params, a, b, rnd, /**/ &fx, &fy, &fz);
            xforce += fx;
            yforce += fy;
            zforce += fz;

            sentry = 3 * bid;
            atomicAdd(ff_src + sentry,     -fx);
            atomicAdd(ff_src + sentry + 1, -fy);
            atomicAdd(ff_src + sentry + 2, -fz);
        }
    }
    fA[X] += xforce; fA[Y] += yforce; fA[Z] += zforce;
}

template <typename Par>
__global__ void halo(Par params, int3 L, float seed,
                     const int27 starts, int n_dst, Pap26 hpp,
                     const int *cellstarts, const uint *ids_src, const float2 *pp_src,
                     /**/ Fop26 hff, float *ff_src) {
    int aid, start;
    int fid;
    PairPa a;
    float *fA;

    aid = threadIdx.x + blockDim.x * blockIdx.x;
    if (aid >= n_dst) return;

    fid = frag_dev::frag_get_fid(starts.d, aid);
    start = starts.d[fid];
    fetch(aid - start, (const float2*)hpp.d[fid], &a);
    fA = hff.d[fid][aid - start].f;
    interactions_one_p(params, L, seed, a, aid, cellstarts, ids_src, pp_src,
                       /**/ ff_src, fA);
}
/* end src/cnt/dev/halo.h */
}

