/* already included: src/inc/type.h */

/* already included: src/control/outflow/imp.h */

/* begin src/control/outflow/imp/type.h */
enum {
    OUTFLOW_TYPE_NONE,
    OUTFLOW_TYPE_PLATE,
    OUTFLOW_TYPE_CIRCLE
};

struct OutflowParamsCircle {
    float Rsq;  /* radius squared  */
    float3 c;   /* center          */
};

/* plane is described as a*x + b*y + c*z + d = 0 */
struct OutflowParamsPlate {
    float a, b, c, d;
};

union OutflowParamsU {
    OutflowParamsPlate plate;
    OutflowParamsCircle circle;
};

struct Outflow {
    int *kk;        /* die or stay alive?      */
    int *ndead_dev; /* number of kills on dev  */
    int ndead;      /* number of kils          */

    OutflowParamsU params; /* shape parameters */
    int type;       /* shape type       */
};
/* end src/control/outflow/imp/type.h */

namespace outflow_dev {
/* begin src/control/outflow/dev/main.h */
static __device__ int predicate(OutflowParamsPlate p, const float r[3]) {
    enum {X, Y, Z};
    float s;

    s = p.a * r[X] + p.b * r[Y] + p.c * r[Z] + p.d;

    return s > 0;
}

static __device__ int predicate(OutflowParamsCircle p, const float r[3]) {
    enum {X, Y, Z};
    float x, y, rsq;
    x = r[X] - p.c.x;
    y = r[Y] - p.c.y;

    rsq = x*x + y*y;
    return rsq > p.Rsq;
}

template <typename Par>
__global__ void filter(int n, const Particle *pp, Par params, /**/ int *ndead, int *kk) {
    int i = threadIdx.x + blockIdx.x * blockDim.x;
    int dead;
    Particle p;
    if (i >= n) return;

    p = pp[i];
    dead = predicate(params, p.r);
    kk[i] = dead;
    if (dead)
        atomicAdd(ndead, 1);
}

/* end src/control/outflow/dev/main.h */
}

/* begin src/control/outflow/imp/main.h */
static void reset_ndead(Outflow *o) {
    CC(d::MemsetAsync(o->ndead_dev, 0, sizeof(int)));
    o->ndead = 0;
}

void outflow_ini(int maxp, /**/ Outflow **o0) {
    Outflow *o;
    size_t sz;

    EMALLOC(1, o0);
    o = *o0;

    sz = maxp * sizeof(int);
    Dalloc(&o->kk, maxp);
    Dalloc(&o->ndead_dev, 1);

    CC(d::MemsetAsync(o->kk, 0, sz));
    UC(reset_ndead(o));
    o->type = OUTFLOW_TYPE_NONE;
}

void outflow_fin(/**/ Outflow *o) {
    Dfree(o->kk);
    Dfree(o->ndead_dev);
    EFREE(o);
}

void outflow_set_params_circle(const Coords *coords, float3 c, float R, Outflow *o) {
    enum {X, Y, Z};
    OutflowParamsCircle p;
    p.Rsq = R*R;

    // shift to local referential
    global2local(coords, c, /**/ &p.c);

    o->params.circle = p;
    o->type = OUTFLOW_TYPE_CIRCLE;
}

void outflow_set_params_plate(const Coords *c, int dir, float r0, Outflow *o) {
    enum {X, Y, Z};
    OutflowParamsPlate p = {0, 0, 0, 0};

    switch (dir) {
    case X:
        p.a = 1;
        p.d = xg2xl(c, r0);
        break;
    case Y:
        p.b = 1;
        p.d = yg2yl(c, r0);
        break;
    case Z:
        p.c = 1;
        p.d = zg2zl(c, r0);
        break;
    default:
        ERR("undefined direction %d\n", dir);
        break;
    };

    o->params.plate = p;
    o->type = OUTFLOW_TYPE_PLATE;
}

void outflow_filter_particles(int n, const Particle *pp, /**/ Outflow *o) {
    reset_ndead(o);

    switch(o->type) {
    case OUTFLOW_TYPE_CIRCLE:
        KL(outflow_dev::filter, (k_cnf(n)), (n, pp, o->params.circle, /**/ o->ndead_dev, o->kk) );
        break;
    case OUTFLOW_TYPE_PLATE:
        KL(outflow_dev::filter, (k_cnf(n)), (n, pp, o->params.plate, /**/ o->ndead_dev, o->kk) );
        break;
    case OUTFLOW_TYPE_NONE:
    default:
        ERR("No type set");
        break;
    };
}

void outflow_download_ndead(Outflow *o) {
    CC(d::Memcpy(&o->ndead, o->ndead_dev, sizeof(int), D2H));
    // printf("killed %d particles\n", o->ndead);
}

int* outflow_get_deathlist(Outflow *o) {return o->kk;}
int  outflow_get_ndead(Outflow *o)     {return o->ndead;}
/* end src/control/outflow/imp/main.h */
/* end src/control/outflow/imp.cu */

