namespace frag_hst {

void estimates(int3 L, int nfrags, float maxd, /**/ int *cap) {
    int i, e;
    for (i = 0; i < nfrags; ++i) {
        e = ncell(L, i);
        e = (int) (e * maxd);
        cap[i] = e;
    }
}

