/* begin src/he/hash.cpp */
#include <stdio.h>
/* begin src/he/memory.h */
#define MALLOC(n, pp) he_malloc((n)*sizeof(**(pp)), (void**)(pp))
#define FREE(p) he_free(p)
#define MEMCPY(n, src, dest) he_memcpy((void*)(dest), (const void*)(src), (n)*sizeof(*(dest)))

int he_malloc(int, void**);
int he_free(void *ptr);
int he_memcpy(void *dest, const void *src, size_t n);
/* end src/he/memory.h */
/* already included: src/he/err.h */
/* begin src/he/hash.h */
#define T HeHash

typedef struct T T;

int he_hash_ini(int n, T**);

/* hash[i, j] = v */
int he_hash_set(T*, int i, int j, int v);

/* ans = hash[i, j], ans = -1 if unset  */
int he_hash_get(T*, int i, int j);
int he_hash_fin(T*);

#undef T
/* end src/he/hash.h */

#define T HeHash
#define E(fmt, ...) ERR(HE_INDEX, fmt, ##__VA_ARGS__);

typedef struct Node Node;
struct Node {
    int j;
    int v; /* value */
    Node  *nxt;
};
struct T {
    int n;
    Node **node;
};

int he_hash_ini(int n, T **pq) {
    T *q;
    int i;
    MALLOC(1, &q);
    MALLOC(q->n = n, &q->node);
    for (i = 0; i < n; i++)
        q->node[i] = NULL;
    *pq = q;
    return HE_OK;
}

static void free_node(Node *p) {
    Node *n;
    while (p != NULL) {
        n = p->nxt;
        FREE(p);
        p = n;
    }
}
int he_hash_fin(T *q) {
    int n, i;
    n = q->n;
    for (i = 0; i < n; i++)
        free_node(q->node[i]);
    FREE(q->node);
    FREE(q);
    return HE_OK;
}

int he_hash_set(T *q, int i, int j, int v) {
    int n;
    Node *nxt, *prv, *nnew;
    n = q->n;
    if (0 > i || i >= n || 0 > j || j >= n)
        E("[%d %d], n = %d", i, j, n);

    prv = q->node[i];
    while (prv != NULL) {
        if (prv->j == j) {
            prv->v = v;
            return HE_OK;
        }
        nxt = prv->nxt;
        if (nxt == NULL) break;
        prv = nxt;
    }

    MALLOC(1, &nnew);
    nnew->j = j;
    nnew->v = v;
    nnew->nxt = NULL;
    if (prv == NULL) q->node[i] = nnew;
    else prv->nxt = nnew;
    return HE_OK;
}

int he_hash_get(T *q, int i, int j) {
    int n;
    Node *node;
    n = q->n;
    if (0 > i || i >= n || 0 > j || j >= n)
        E("[%d %d], n = %d", i, j, n);
    node = q->node[i];
    while (node != NULL) {
        if (node->j == j) return node->v;
        node = node->nxt;
    }
    return -1;
}
/* end src/he/hash.cpp */

