/* begin src/inter/color/imp/type.h */
enum {
    INTER_COLOR_NONE,
    INTER_COLOR_DROP,
    INTER_COLOR_UNIF
};

struct GenColor {
    int kind;
    float R;
};
/* end src/inter/color/imp/type.h */
/* begin src/inter/color/imp/unif.h */
static void set_color_unif(int n, /**/ int* cc) {
    int i;
    for (i = 0; i < n; i++) cc[i] = BLUE_COLOR;
}
/* end src/inter/color/imp/unif.h */
/* begin src/inter/color/imp/drop.h */
static void set_color_drop(float rad, const Coords *coords, int n, const Particle *pp, /**/ int *cc) {
    enum {X, Y, Z};
    int lx, ly, lz; /* domain */
    int i, r, g;
    bool inside;
    float x, y, z;
    float x0, y0, z0;
    Particle p;

    lx = xdomain(coords);
    ly = ydomain(coords);
    lz = zdomain(coords);

    x0 = 0.5*lx; y0 = 0.5*ly; z0 = 0.5*lz;
    enum {R = RED_COLOR, G = BLUE_COLOR};
    for (i = r = g = 0; i < n; i++) {
        p = pp[i];
        x = p.r[X]; y = p.r[Y]; z = p.r[Z];
        x = xl2xg(coords, x);
        y = yl2yg(coords, y);
        z = zl2zg(coords, z);
        x -= x0; y -= y0; z -= z0;
        inside = x*x + y*y + z*z < rad*rad;
        if (inside) {cc[i] = R; r++;}
        else        {cc[i] = G; g++;}
    }
    msg_print("color scheme: Bangladesh");
    msg_print("red/green : %d/%d", r, g);
}
/* end src/inter/color/imp/drop.h */
/* begin src/inter/color/imp/main.h */
void inter_color_ini(GenColor **c) {
    GenColor *gc;
    EMALLOC(1, c);
    gc = *c;
    gc->kind = INTER_COLOR_NONE;
}

void inter_color_fin(GenColor *c) {
    EFREE(c);
}

void inter_color_set_drop(float R, GenColor *c) {
    c->kind = INTER_COLOR_DROP;
    c->R = R;
}

void inter_color_set_uniform(GenColor *c) {
    c->kind = INTER_COLOR_UNIF;
}

void inter_color_apply_hst(const Coords *coords, const GenColor *gc, int n, const Particle *pp, /**/ int *cc) {
    switch (gc->kind) {
    case INTER_COLOR_UNIF:
        set_color_unif(n, /**/ cc);
        break;
    case INTER_COLOR_DROP:
        set_color_drop(gc->R, coords, n, pp, /**/ cc);
        break;
    case INTER_COLOR_NONE:
        break;
    default:
        ERR("Unrecognised kind <%d>", gc->kind);
        break;
    };
}

void inter_color_apply_dev(const Coords *coords, const GenColor *gc, int n, const Particle *pp, /**/ int *cc) {
    int *cc_hst;
    Particle *pp_hst;

    if (gc->kind == INTER_COLOR_NONE) return;

    EMALLOC(n, &cc_hst);
    EMALLOC(n, &pp_hst);

    cD2H(pp_hst, pp, n);

    UC(inter_color_apply_hst(coords, gc, n, pp_hst, /**/ cc_hst));

    cH2D(cc, cc_hst, n);

    EFREE(pp_hst);
    EFREE(cc_hst);
}
/* end src/inter/color/imp/main.h */
/* end src/inter/color/imp.cpp */

