/* begin src/mesh/area/imp.h */
struct MeshArea;
struct Vectors;
struct MeshRead;

// tag::interface[]
void mesh_area_ini(MeshRead*, /**/ MeshArea**); // <1>
void mesh_area_fin(MeshArea*);

double mesh_area_apply0(MeshArea*, Vectors*);                     // <2>
void  mesh_area_apply(MeshArea*, int nm, Vectors*, /**/ double*); // <3>
// end::interface[]
/* end src/mesh/area/imp.h */
/* begin src/mesh/area/imp/type.h */
struct MeshArea {
    int4 *tt;
    int nv, nt;
};
/* end src/mesh/area/imp/type.h */
/* begin src/mesh/area/imp/main.h */
void mesh_area_ini(MeshRead *mesh, MeshArea **pq) {
    int nv, nt;
    MeshArea *q;
    EMALLOC(1, &q);
    nt = mesh_read_get_nt(mesh);
    nv = mesh_read_get_nv(mesh);
    EMALLOC(nt, &q->tt);

    q->nv = nv; q->nt = nt;
    EMEMCPY(nt, mesh_read_get_tri(mesh), q->tt);

    *pq = q;
}

void mesh_area_fin(MeshArea *q) { EFREE(q->tt); EFREE(q); }
static void area_get(Vectors *p, int i, double d[3]) {
    enum {X, Y, Z};
    float f[3];
    UC(vectors_get(p, i, /**/ f));
    d[X] = f[X]; d[Y] = f[Y]; d[Z] = f[Z];
}
static double area(int nt, int4 *tt, Vectors *p, int offset) {
    int i, ia, ib, ic;
    double a[3], b[3], c[3], sum;
    KahanSum *kahan_sum;
    kahan_sum_ini(&kahan_sum);
    for (i = 0; i < nt; i++) {
        ia = tt[i].x; ib = tt[i].y; ic = tt[i].z;
        UC(area_get(p, ia + offset, /**/ a));
        UC(area_get(p, ib + offset, /**/ b));
        UC(area_get(p, ic + offset, /**/ c));
        kahan_sum_add(kahan_sum, tri_hst::kahan_area(a, b, c));
    }
    sum = kahan_sum_get(kahan_sum);
    return sum;
}
double mesh_area_apply0(MeshArea *q, Vectors *p) {
    int nt, offset;
    int4 *tt;
    nt = q->nt; tt = q->tt; offset = 0;
    return area(nt, tt, p, offset);
}

void mesh_area_apply(MeshArea *q, int m, Vectors *p, double *area0) {
    int i, nt, nv, offset;
    int4 *tt;
    nt = q->nt; tt = q->tt; nv = q->nv; offset = 0;

    for (i = 0; i < m; i++) {
        UC(area0[i] = area(nt, tt, p, offset));
        offset += nv;
    }
}
/* end src/mesh/area/imp/main.h */

/* end src/mesh/area/imp.cpp */

