void triangles_ini(MeshRead *mesh, /**/ Triangles **pq) {
    int nt;
    Triangles *q;
    const int4 *hst;
    int4 *dev;
    EMALLOC(1, &q);
    *pq = q;
    nt = mesh_read_get_nt(mesh);
    hst = mesh_read_get_tri(mesh);
    Dalloc(&dev, nt);
    cH2D(dev, hst, nt);

    q->nt = nt; q->tt = dev;
}

void triangles_fin(Triangles *q) {
    Dfree(q->tt);
    EFREE(q);
}
