/* begin src/mesh/vert_area/imp/type.h */
struct MeshVertArea {
    int4 *tt;
    int nv, nt;
};
/* end src/mesh/vert_area/imp/type.h */
/* begin src/mesh/vert_area/imp/main.h */
void mesh_vert_area_ini(MeshRead *mesh, MeshVertArea **pq) {
    int nv, nt;
    MeshVertArea *q;
    EMALLOC(1, &q);
    nt = mesh_read_get_nt(mesh);
    nv = mesh_read_get_nv(mesh);
    EMALLOC(nt, &q->tt);

    q->nv = nv; q->nt = nt;
    EMEMCPY(nt, mesh_read_get_tri(mesh), q->tt);

    *pq = q;
}

void mesh_vert_area_fin(MeshVertArea *q) { EFREE(q->tt); EFREE(q); }
static void vert_area_get(Vectors *p, int i, double d[3]) {
    enum {X, Y, Z};
    float f[3];
    UC(vectors_get(p, i, /**/ f));
    d[X] = f[X]; d[Y] = f[Y]; d[Z] = f[Z];
}
static void area(int4 t, Vectors *p, int offset, /**/ double *o) {
    int ia, ib, ic;
    double a[3], b[3], c[3], A;
    ia = t.x; ib = t.y; ic = t.z;
    UC(vert_area_get(p, ia + offset, /**/ a));
    UC(vert_area_get(p, ib + offset, /**/ b));
    UC(vert_area_get(p, ic + offset, /**/ c));

    A = tri_hst::kahan_area(a, b, c)/3;
    o[ia + offset] += A;
    o[ib + offset] += A;
    o[ic + offset] += A;
}

void mesh_vert_area_apply(MeshVertArea *q, int nm, Vectors *pos, double *o) {
    int i, j, nt, nv, n, offset;
    int4 *tt;
    nt = q->nt; tt = q->tt; nv = q->nv; offset = 0;
    n = nv * nm;
    for (i = 0; i < n; i++) o[i] = 0;

    for (i = 0; i < nm; i++) {
        for (j = 0; j < nt; j++)
            area(tt[j], pos, offset, /**/ o);
        offset += nv;
    }
}
/* end src/mesh/vert_area/imp/main.h */
/* end src/mesh/vert_area/imp.cpp */

