struct RbcStretch;
struct Force;

// tag::interface[]
void rbc_stretch_ini(const char *path, int nv, /**/ RbcStretch**); /* `nv` is for error check */
void rbc_stretch_fin(RbcStretch*);
void rbc_stretch_apply(int nm, const RbcStretch*, /**/ Force*);
// end::interface[]
/* end src/rbc/stretch/imp.h */
namespace rbc_stretch_dev {
/* begin src/rbc/stretch/dev/main.h */
static __device__ void apply0(const float *f, /**/ float *fb) {
    enum {X, Y, Z};
    fb[X] += f[X]; fb[Y] += f[Y]; fb[Z] += f[Z];
}

static __device__ void apply1(int i, int nv, const float *f, Force *ff) {
    int k;
    k = i % nv;
    apply0(&f[3*k], /**/ ff[i].f);
}

__global__ void apply(int n, int nv, const float *f, Force *ff) {
    int i;
    i = threadIdx.x + blockDim.x * blockIdx.x;
    if (i >= n) return;
    apply1(i, nv, f, /**/ ff);
}
/* end src/rbc/stretch/dev/main.h */
}
/* begin src/rbc/stretch/imp/type.h */
struct RbcStretch {
    int nv; /* number of vertices */
    float *f; /* force: 3*nv */
};
/* end src/rbc/stretch/imp/type.h */
/* begin src/rbc/stretch/imp/main.h */
static void alloc(int n, RbcStretch *f) { Dalloc(&f->f, 3*n); }
static void dealloc(RbcStretch *f) { Dfree(f->f); }

static int read3(FILE *f, float *h) {
    enum {X, Y, Z};
    int n;
    n = fscanf(f, "%f %f %f\n", &h[X], &h[Y], &h[Z]);
    return n;
}

static void read(FILE *f, int n, /**/ float *h) {
    int i;
    i = 0;
    for (/**/ ; i < n && read3(f, h) == 3;   i++, h += 3)
        ;
    if (i != n) ERR("got %d != %d lines", i, n);
}

static void ini0(const char* path, int n, float *h, /**/ float *d) {
    FILE *f;
    msg_print("read '%s'", path);
    UC(efopen(path, "r", /**/ &f));
    read(f, n , /**/ h);
    cH2D(d, h, 3*n);
    UC(efclose(f));
}

static void ini1(const char* path, int n, /**/ RbcStretch *f) {
    float *d, *h; /* device and host */
    alloc(n, f);
    d = f->f;
    EMALLOC(3 * n, &h);
    UC(ini0(path, n, /*w*/ h, /**/ d));
    EFREE(h);
}

void rbc_stretch_ini(const char* path, int nv, /**/ RbcStretch **fp) {
    RbcStretch *f;
    EMALLOC(1, &f);
    UC(ini1(path, nv, f));
    f->nv = nv;
    *fp = f;
}

void rbc_stretch_fin(RbcStretch *f) {
    dealloc(f);
    EFREE(f);
}

void rbc_stretch_apply(int nm, const RbcStretch *f, /**/ Force *ff) {
    int n, nv;
    nv = f->nv;
    n  = nm * nv;
    if (n) KL(rbc_stretch_dev::apply, (k_cnf(n)), (n, nv, f->f, /**/ ff));
}
/* end src/rbc/stretch/imp/main.h */
/* end src/rbc/stretch/imp.cu */

